def s11() -> str:
    b = slide(
        19, "Слайд «Цепочка ответственности»: вы формулируете запрос; ИИ выдаёт черновик; вы проверяете; вы подписываете и отправляете; сервис не отвечает за ваше решение",
        ["Итоговое правило урока: <b>за результат отвечаете вы</b>. ИИ — инструмент, как калькулятор или поисковик: он может подготовить черновик, но не берёт на себя решение, подпись и последствия. Что бы ни произошло по цепочке «запрос → черновик → проверка → подпись», отвечает тот, кто поставил подпись и отправил документ.",
         "Ответственность бывает разной: дисциплинарной (вплоть до увольнения по ст. 81 ТК РФ за разглашение охраняемой законом тайны), материальной, административной (например, за нарушения правил обработки персональных данных, КоАП РФ ст. 13.11), в тяжёлых случаях — уголовной (ст. 183 и 272.1 УК РФ). Какая именно — зависит от ситуации, и оценивают её уполномоченные лица и суд. Вам достаточно помнить: подпись под документом — это принятие ответственности за его содержание."],
        example="Сообщите руководителю ИИ-справку с выдуманной цифрой. «Так написала нейросеть» — не аргумент: подпись и отправка ваши.",
        takeaway="Подписал — значит проверил и отвечаешь.")
    b += real_case(
        "Суд: выгрузка отчётов в нейросеть — разглашение тайны",
        "Июль 2026 · Бабушкинский районный суд Москвы, дело № 02-1545/2026",
        "Директор по продажам московской компании выгружала внутренние отчёты из корпоративной системы в DeepSeek и отправляла служебные документы на личную почту. Компания уволила её по пп. «в» п. 6 ч. 1 ст. 81 ТК РФ (разглашение охраняемой законом тайны). Суд признал увольнение законным и отклонил требования об изменении формулировки и выплате «золотого парашюта». Позиция суда: у сотрудницы не было производственной необходимости размещать эти сведения на внешнем сервисе. По оценке юристов, это первый опубликованный акт такого рода.",
        "Доказывать, что данные кто-то прочитал, не потребовалось. Достаточно того, что они были загружены в сторонний сервис без производственной необходимости.",
        [("РАПСИ · Суд признал законным увольнение за загрузку коммерческих данных в DeepSeek (27.07.2026)", "https://rapsinews.ru/moscourts_news/20260727/312063726.html"),
         ("Право.ру · Работника уволили за передачу корпоративной тайны DeepSeek", "https://pravo.ru/news/264969/"),
         ("Хабр · Суд признал законным увольнение сотрудницы московской компании за отправку данных в DeepSeek", "https://habr.com/ru/news/1063374/")])
    b += real_case(
        "Чат-бот ошибся, а платить пришлось компании",
        "Февраль 2024 · Канада, Moffatt v. Air Canada, 2024 BCCRT 149",
        "Пассажир воспользовался советом чат-бота авиакомпании о том, как получить скидку на билет при трауре, а позже выяснилось, что правила другие. Авиакомпания отказывалась отвечать за бота, утверждая, что он — «отдельный субъект». Трибунал не согласился: компания отвечает за всю информацию на своём сайте, включая чат-бота, и должна была проявить разумную осторожность, чтобы информация была точной.",
        "Ссылка «это бот ошибся» не снимает ответственности ни с организации, ни с сотрудника. Ошибка машины остаётся ошибкой того, кто её использует.",
        [("McCarthy Tétrault · Moffatt v. Air Canada: A Misrepresentation by an AI Chatbot", "https://www.mccarthy.ca/en/insights/blogs/techlex/moffatt-v-air-canada-misrepresentation-ai-chatbot"),
         ("American Bar Association · BC Tribunal Confirms Companies Remain Liable for Information Provided by AI Chatbot", "https://www.americanbar.org/groups/business_law/resources/business-law-today/2024-february/bc-tribunal-confirms-companies-remain-liable-information-provided-ai-chatbot/")])
    b += slide(
        20, "Слайд «Пять проверок результата ИИ»: достоверность, источник, права и согласие, предвзятость и последствия, ответственность; формула: результат ИИ → риск → проверка → действие человека → решение",
        ["Пять проверок — итог второй пары, и его стоит запомнить целиком. <b>1. Достоверность:</b> это правда? <b>2. Источник:</b> откуда это взялось и подтверждает ли источник именно это? <b>3. Права и согласие:</b> можем ли мы это использовать? <b>4. Предвзятость и последствия:</b> кого и как может затронуть результат? <b>5. Ответственность:</b> кто принимает окончательное решение об использовании?",
         "Формула: РЕЗУЛЬТАТ ИИ → РИСК → ПРОВЕРКА → ДЕЙСТВИЕ ЧЕЛОВЕКА → РЕШЕНИЕ ОБ ИСПОЛЬЗОВАНИИ. Вместе с формулой пары 1 она образует сквозную цепочку: подготовил информацию → передал минимум необходимого → получил результат → проверил риски → принял решение."],
        takeaway="Не запрещать ИИ, а использовать его ответственно.")
    b += table("Связка двух пар: до обращения к ИИ и после получения результата",
               ["До обращения к ИИ — пара 1", "После получения результата — пара 2"],
               [["Какие данные действительно нужны?", "Насколько достоверен результат?"],
                ["Что можно удалить?", "Можно ли подтвердить источники и факты?"],
                ["Что нужно обезличить или обобщить?", "Есть ли правовые и репутационные риски?"],
                ["Что проверить в настройках хранения и конфиденциальности?", "Есть ли предвзятость, синтетический контент, вопросы согласия?"],
                ["Можно ли передавать эту информацию?", "Можно ли использовать результат и кто принимает решение?"]])
    b += practice(
        "11", "Итоговое задание пары 2: моя строка проверки",
        '<p>Выберите один тип результата ИИ, который вы потенциально можете использовать в своей работе (справка, письмо, презентация, изображение, рекомендация по людям), и заполните одну строку.</p>',
        ["Заполните строку таблицы для своего типа результата.",
         "Проверьте себя по пяти проверкам со слайда 20.",
         "Допишите фразу: «Перед использованием результата ИИ я сначала буду…»."],
        ["Строка заполнена: результат, главный риск, что проверить, что сделает человек, решение.",
         "У вас есть личное правило одной фразой.",
         "Вы знаете, кому в организации адресовать вопросы, на которые сами ответить не можете."],
        extra='<table class="mini-tbl"><thead><tr><th>Результат ИИ</th><th>Главный риск</th><th>Что проверить</th><th>Что сделать человеку</th><th>Решение</th></tr></thead><tbody><tr><td>&nbsp;</td><td></td><td></td><td></td><td></td></tr></tbody></table><p class="q-hint">Exit ticket: «Перед использованием результата ИИ я сначала буду…»</p>')
    b += card("Домашнее задание (до следующего занятия)",
              steps(["Заполните паспорт безопасной задачи (пара 1) для двух своих типов рабочих задач. Реальных данных не пишите — только типы информации и способы подготовки.",
                     "Выберите один недавний результат ИИ (или вымышленный пример) и пройдите по нему пять проверок пары 2. Запишите, что нашли.",
                     "Вопросы, на которые не смогли ответить, сформулируйте для ответственного по информационной безопасности или юридической функции вашего предприятия. Ответов на них в этом уроке нет намеренно: они зависят от локальных актов.",
                     "Сдайте одним файлом: две строки паспорта, результат проверки и список вопросов."])
              + '<p class="q-hint">Личный чек-лист остаётся у вас. Перед отправкой проверьте, что в файле нет реальных названий, фамилий и рабочих данных.</p>')
    return sec("s11", "11", "Ответственность пользователя за итоговый результат",
               "Сводим вторую пару в одно правило: за то, что вы подписали и отправили, отвечаете вы, а не нейросеть.", b, "76–90 мин")


def pair2_sections() -> str:
    return s7() + s8() + s9() + s10() + s11()
